import { BufferJSON } from '../../Utils/generics'
import { SenderKeyState } from './sender-key-state'

export interface SenderKeyStateStructure {
	senderKeyId: number
	senderChainKey: {
		iteration: number
		seed: Uint8Array
	}
	senderSigningKey: {
		public: Uint8Array
		private?: Uint8Array
	}
	senderMessageKeys: Array<{
		iteration: number
		seed: Uint8Array
	}>
}

/**
 * SenderKeyRecord - Armazena múltiplos estados de chave de remetente
 * Implementação robusta com validação defensiva de tipos
 */
export class SenderKeyRecord {
	private readonly MAX_STATES = 5
	private readonly senderKeyStates: SenderKeyState[] = []

	constructor(serialized?: SenderKeyStateStructure[] | unknown) {
		// Validação robusta do parâmetro serialized
		if (serialized !== null && serialized !== undefined) {
			// Verificar se é iterável e não é um tipo primitivo
			if (!this.isValidSerializedData(serialized)) {
				return
			}

			try {
				const dataArray = Array.isArray(serialized) ? serialized : []

				for (const structure of dataArray) {
					if (this.isValidStateStructure(structure)) {
						try {
							this.senderKeyStates.push(new SenderKeyState(null, null, null, null, null, null, structure))
						} catch (stateError) {
							// Ignorar estruturas inválidas
						}
					}
				}
			} catch (error) {
				this.senderKeyStates = []
			}
		}
	}

	/**
	 * Valida se os dados são iteráveis e do tipo esperado
	 */
	private isValidSerializedData(data: unknown): data is SenderKeyStateStructure[] {
		// Rejeitar tipos primitivos
		if (typeof data === 'number' || typeof data === 'string' || typeof data === 'boolean') {
			return false
		}

		// Rejeitar null/undefined
		if (data === null || data === undefined) {
			return false
		}

		// Verificar se é iterável
		if (typeof (data as Iterable<unknown>)[Symbol.iterator] !== 'function') {
			return false
		}

		// Preferir arrays
		return Array.isArray(data)
	}

	/**
	 * Valida se a estrutura de estado é válida
	 */
	private isValidStateStructure(structure: unknown): structure is SenderKeyStateStructure {
		// Rejeitar tipos primitivos
		if (typeof structure !== 'object' || structure === null) {
			return false
		}

		// Verificar propriedades mínimas esperadas
		const hasValidProps =
			'senderKeyId' in structure ||
			'senderChainKey' in structure ||
			'senderSigningKey' in structure ||
			'senderMessageKeys' in structure

		return hasValidProps || Object.keys(structure).length > 0
	}

	public isEmpty(): boolean {
		return this.senderKeyStates.length === 0
	}

	public getSenderKeyState(keyId?: number): SenderKeyState | undefined {
		if (keyId === undefined && this.senderKeyStates.length) {
			return this.senderKeyStates[this.senderKeyStates.length - 1]
		}

		return this.senderKeyStates.find(state => state.getKeyId() === keyId)
	}

	public addSenderKeyState(id: number, iteration: number, chainKey: Uint8Array, signatureKey: Uint8Array): void {
		// Validar signatureKey antes de adicionar
		if (!signatureKey || signatureKey.length < 32) {
			return
		}
		
		this.senderKeyStates.push(new SenderKeyState(id, iteration, chainKey, null, signatureKey))
		if (this.senderKeyStates.length > this.MAX_STATES) {
			this.senderKeyStates.shift()
		}
	}

	public setSenderKeyState(
		id: number,
		iteration: number,
		chainKey: Uint8Array,
		keyPair: { public: Uint8Array; private: Uint8Array }
	): void {
		this.senderKeyStates.length = 0
		this.senderKeyStates.push(new SenderKeyState(id, iteration, chainKey, keyPair))
	}

	public serialize(): SenderKeyStateStructure[] {
		return this.senderKeyStates.map(state => state.getStructure())
	}

	/**
	 * Deserializa dados em um SenderKeyRecord
	 * Implementação robusta com múltiplas camadas de validação
	 */
	static deserialize(data: Uint8Array | Buffer | string | unknown): SenderKeyRecord {
		// Validação de entrada
		if (data === null || data === undefined) {
			return new SenderKeyRecord()
		}

		// Rejeitar tipos primitivos
		if (typeof data === 'number' || typeof data === 'boolean') {
			return new SenderKeyRecord()
		}

		try {
			let str: string

			// Converter para string de forma segura
			if (Buffer.isBuffer(data)) {
				str = data.toString('utf-8')
			} else if (data instanceof Uint8Array || data instanceof ArrayBuffer) {
				str = Buffer.from(data as Uint8Array).toString('utf-8')
			} else if (typeof data === 'string') {
				str = data
			} else if (Array.isArray(data)) {
				return new SenderKeyRecord(data as SenderKeyStateStructure[])
			} else {
				try {
					str = Buffer.from(data as Uint8Array).toString('utf-8')
				} catch {
					return new SenderKeyRecord()
				}
			}

			if (!str || str.trim() === '') {
				return new SenderKeyRecord()
			}

			let parsed: unknown
			try {
				parsed = JSON.parse(str, BufferJSON.reviver)
			} catch {
				return new SenderKeyRecord()
			}

			if (!Array.isArray(parsed)) {
				if (typeof parsed === 'object' && parsed !== null) {
					parsed = [parsed]
				} else {
					return new SenderKeyRecord()
				}
			}

			return new SenderKeyRecord(parsed as SenderKeyStateStructure[])
		} catch {
			return new SenderKeyRecord()
		}
	}
}
